<script setup lang="ts">
import { computed,ref } from 'vue'
import type { AiSettings,AiTask } from '../../../../contracts/index'
import type { LocalModelsApi,LocalModelView } from '../../../../contracts/models/local-model-contracts'
import { LOCAL_CONNECTION_ID } from '../../../../contracts/models/local-model-contracts'
import { useLocalModels } from '../composables/use-local-models'
const props=defineProps<{api:LocalModelsApi;settings:AiSettings;busy?:boolean}>()
const emit=defineEmits<{use:[model:LocalModelView,target:'shared'|AiTask];changed:[]}>()
const {models,loading,checking,error,refresh,inspect,cancel}=useLocalModels(props.api)
const query=ref(''),installedOnly=ref(false),target=ref<'shared'|AiTask>('shared')
const visible=computed(()=>models.value.filter(m=>(!installedOnly.value||m.state!=='not-installed')&&(!query.value||[m.name,m.family,m.description].join(' ').toLowerCase().includes(query.value.toLowerCase()))))
const readyCount=computed(()=>models.value.filter(m=>m.state==='ready').length)
const labels:Record<string,string>={'not-installed':'未安装',detected:'已发现',verifying:'校验中',downloading:'下载中',installing:'安装中',checking:'检测中',ready:'可使用',failed:'检测失败',cancelled:'已停止',interrupted:'待重新检测'}
const assignments=(id:string)=>props.settings.routingMode==='shared'?(props.settings.shared.connectionId===LOCAL_CONNECTION_ID&&props.settings.shared.model===id?'全部写作任务':''):Object.entries(props.settings.tasks).filter(([,p])=>p.connectionId===LOCAL_CONNECTION_ID&&p.model===id).map(([key])=>({outline:'总纲',chapterOutline:'章纲',prose:'正文',review:'审校'}[key])).join('、')
async function check(id:string){await inspect(id);emit('changed')}
</script>
<template>
<section class="local-model-store" data-testid="local-model-store">
  <header class="store-heading"><div><span class="store-eyebrow">LANJIAN · LOCAL INTELLIGENCE · BETA</span><h2>本地模型商店</h2><p>体验本机模型与写作流程，生成篇幅和质量取决于模型能力。</p></div><div class="store-count"><strong>{{ readyCount }}</strong><span>个模型可使用</span></div></header>
  <div class="store-toolbar"><div role="group" aria-label="模型范围"><button type="button" :aria-pressed="!installedOnly" :class="{active:!installedOnly}" @click="installedOnly=false">全部模型</button><button type="button" :aria-pressed="installedOnly" :class="{active:installedOnly}" @click="installedOnly=true">本机资源</button></div><label class="store-search"><span>搜索</span><input v-model="query" aria-label="搜索本地模型" placeholder="名称或用途"></label></div>
  <p v-if="error" role="alert" class="store-error">{{ error }} <button type="button" @click="refresh">重新读取</button></p>
  <p v-if="loading" role="status">正在读取模型目录……</p>
  <p v-else-if="!visible.length" class="store-empty">没有找到匹配的模型。</p>
  <article v-for="model in visible" :key="model.id" class="store-model" :data-model-id="model.id">
    <div class="model-art" aria-hidden="true"><span>千</span><small>QWEN / LOCAL</small><i></i></div>
    <div class="store-model-body"><div class="model-title"><div><span class="model-series">{{ model.family }} · 中文文字模型</span><h3>{{ model.name }}</h3></div><span class="model-state" :class="{ready:model.state==='ready'}" role="status" :data-state="model.state"><i></i>{{ labels[model.state] }}</span></div>
      <p class="model-description">{{ model.description }}</p>
      <dl class="model-facts"><div><dt>模型大小</dt><dd>{{ (model.bytes/1024**3).toFixed(2) }} GB</dd></div><div><dt>量化版本</dt><dd>{{ model.quantization }}</dd></div><div><dt>上下文</dt><dd>{{ (model.contextTokens/1024).toFixed(0) }} K tokens</dd></div><div><dt>许可证</dt><dd>{{ model.license }}</dd></div></dl>
      <div class="model-uses"><span>总纲</span><span>章纲</span><span>正文草稿</span><span>审校</span><span>本机运行</span></div>
      <div v-if="checking===model.id" class="model-progress"><progress :value="model.progress" max="100" :aria-label="model.message"></progress><span>{{ model.message }} · {{ model.progress }}%</span></div>
      <p v-else class="model-message" :class="{'store-error':model.state==='failed'}">{{ model.message }}</p>
      <p v-if="assignments(model.id)" class="model-assigned">当前用于：{{ assignments(model.id) }}</p>
      <footer class="model-actions"><button v-if="checking===model.id" class="control-button secondary" type="button" @click="cancel">停止检测</button><button v-else class="control-button secondary" type="button" :disabled="busy||!!checking||model.state==='not-installed'" :data-testid="'inspect-'+model.id" @click="check(model.id)">{{ model.state==='ready'?'重新检测':'检测并启用' }}</button><div class="model-assign"><select v-model="target" aria-label="本地模型使用模块" :disabled="busy||!!checking"><option value="shared">全部写作任务</option><option value="outline">总纲</option><option value="chapterOutline">章纲</option><option value="prose">正文</option><option value="review">审校</option></select><button class="control-button primary" type="button" :disabled="busy||!!checking||model.state!=='ready'" data-testid="assign-local-model" @click="emit('use',model,target)">选用模型</button></div></footer>
      <details><summary>模型信息</summary><p>检测会校验本机文件并进行真实生成。{{ model.state==='ready'?'当前已通过检测。':'上下文为待检测的运行配置。' }}写作质量以实际候选为准。</p><p>版本 {{ model.revision.slice(0,12) }} · 推荐输出 {{ model.recommendedOutputTokens }} tokens</p></details>
    </div>
  </article>
  <footer class="store-note"><span>模型目录持续扩展</span><p>已有资源直接复用。后续模型将提供下载与安装进度，准备完成后即可分配到支持的模块。</p></footer>
</section>
</template>
<style scoped>
.local-model-store{color:var(--ink);max-width:72rem;margin:0 auto}.store-heading{display:flex;justify-content:space-between;gap:2rem;align-items:center;padding:1rem 0 1.7rem;border-bottom:1px solid var(--line)}.store-eyebrow,.model-series{font-size:.65rem;letter-spacing:.14em;color:var(--muted)}.store-heading h2{font-family:var(--font-display,serif);font-weight:500;font-size:2rem;margin:.55rem 0}.store-heading p{color:var(--muted);margin:0;font-size:.83rem}.store-count{display:grid;text-align:right;gap:.15rem;flex-shrink:0}.store-count strong{font-size:2.25rem;font-weight:400;color:var(--jade)}.store-count span{font-size:.68rem;color:var(--muted)}.store-toolbar{display:flex;justify-content:space-between;gap:1rem;padding:1rem 0;flex-wrap:wrap}.store-toolbar button{background:none;border:0;padding:.55rem .8rem;color:var(--muted);cursor:pointer;font:inherit;font-size:.8rem}.store-toolbar button.active{background:color-mix(in srgb,var(--jade) 10%,transparent);color:var(--jade)}.store-search{display:flex;align-items:center;gap:.5rem;font-size:.75rem;color:var(--muted)}.store-search input{width:12rem;min-width:0;padding:.45rem .6rem;border:1px solid var(--line);background:transparent;color:var(--ink)}.store-model{display:grid;grid-template-columns:10rem minmax(0,1fr);border:1px solid var(--line);background:var(--surface);animation:store-arrive .3s ease-out}.model-art{position:relative;overflow:hidden;display:flex;align-items:center;justify-content:center;flex-direction:column;min-height:20rem;background:color-mix(in srgb,var(--jade) 10%,var(--surface));color:var(--jade);border-right:1px solid var(--line)}.model-art>span{font-family:serif;font-size:4.5rem;font-weight:300;position:relative;z-index:1}.model-art small{font-size:.55rem;letter-spacing:.18em;margin-top:1.3rem;z-index:1}.model-art i{position:absolute;width:13rem;height:13rem;border:1px solid color-mix(in srgb,var(--jade) 20%,transparent);transform:rotate(45deg)}.store-model-body{padding:1.4rem 1.5rem;min-width:0}.model-title{display:flex;justify-content:space-between;align-items:center;gap:.8rem}.model-title h3{font-size:1.35rem;margin:.5rem 0;font-weight:500}.model-state{display:flex;align-items:center;gap:.35rem;white-space:nowrap;font-size:.7rem;color:var(--muted)}.model-state i{width:.35rem;height:.35rem;border-radius:50%;background:currentColor}.model-state.ready{color:var(--jade)}.model-description{color:var(--muted);font-size:.8rem;line-height:1.7;max-width:38rem}.model-facts{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:.6rem;padding:1rem 0;border-block:1px solid var(--line)}.model-facts dt{font-size:.65rem;color:var(--muted);margin-bottom:.5rem}.model-facts dd{font-size:.75rem;margin:0;overflow-wrap:anywhere}.model-uses{display:flex;flex-wrap:wrap;gap:.45rem}.model-uses span{font-size:.66rem;border:1px solid var(--line);padding:.2rem .45rem;color:var(--muted)}.model-message,.model-assigned{font-size:.73rem;line-height:1.6;color:var(--muted)}.model-assigned{color:var(--jade)}.model-actions{display:flex;justify-content:space-between;gap:.7rem;margin-top:1.3rem;flex-wrap:wrap}.model-assign{display:flex;gap:.5rem;align-items:center}.model-assign select{max-width:10rem;padding:.5rem;border:1px solid var(--line);background:var(--surface);color:var(--ink);font:inherit;font-size:.75rem}.model-progress{margin-top:1rem;font-size:.7rem;color:var(--jade);display:grid;gap:.4rem}.model-progress progress{width:100%;height:.25rem;accent-color:var(--jade)}.store-model details{margin-top:1rem;color:var(--muted);font-size:.7rem;line-height:1.7;overflow-wrap:anywhere}.store-model summary{cursor:pointer}.store-note{padding:1.4rem 0;color:var(--muted);font-size:.73rem;line-height:1.7}.store-note>span{letter-spacing:.1em}.store-note p{margin:.4rem 0}.store-error{color:var(--danger,#a64c3c)}.store-empty{padding:3rem 0;color:var(--muted)}button:focus-visible,select:focus-visible,input:focus-visible,summary:focus-visible{outline:2px solid var(--jade);outline-offset:3px}@keyframes store-arrive{from{opacity:0;transform:translateY(5px)}to{opacity:1;transform:none}}@media(max-width:1250px){.store-model{grid-template-columns:6rem minmax(0,1fr)}.store-model-body{padding:1rem}.model-art>span{font-size:3rem}.model-art small{font-size:.4rem}.model-facts{grid-template-columns:repeat(2,minmax(0,1fr))}.store-heading h2{font-size:1.6rem}}@media(max-width:850px){.store-model{grid-template-columns:1fr}.model-art{display:none}.store-count{display:none}.model-assign{flex-wrap:wrap}}
</style>
